// Image de sa ville, au moins 1 200 pixels de large : son nom, sa ville (jamais celle d'une visite) sous le ciel du moment, puis le
// temps pris pour soi.
async function cityImageCanvas() {
  const source = typeof City.snapshot === 'function' ? City.snapshot() : $('#city');
  const width = Math.max(1200, source.width), ratio = width / source.width, margin = Math.round(width * .05), head = Math.round(width * .12), foot = Math.round(width * .065);
  const cityH = Math.round(source.height * ratio);
  const out = document.createElement('canvas');
  out.width = width; out.height = cityH + head + foot;
  const ctx = out.getContext('2d');
  // Le dessin de la ville est transparent : on remet son ciel, et ses étoiles la nuit.
  const sky = paintImageSky(ctx, width, out.height, { x: 0, y: head, w: width, h: cityH });
  const titleFont = '400 ' + Math.round(width * .036) + 'px "Young Serif", Georgia, serif';
  const footFont = '600 ' + Math.round(width * .019) + 'px Figtree, system-ui, sans-serif';
  if (document.fonts && document.fonts.load) await Promise.all([document.fonts.load(titleFont), document.fonts.load(footFont)]).catch(() => {});
  ctx.fillStyle = imageInk(sky, head * .55 / out.height).ink; ctx.textBaseline = 'middle'; ctx.font = titleFont;
  ctx.fillText(frTypo(cityName()), margin, head * .55, width - margin * 2);
  ctx.drawImage(source, 0, head, width, cityH);
  ctx.fillStyle = imageInk(sky, 1 - foot * .5 / out.height).muted; ctx.font = footFont;
  ctx.fillText(frTypo(t('png.footer', { time: fmtEffort(totalEffortMinutes()) })), margin, out.height - foot * .5, width - margin * 2);
  return out;
}
// « Enregistrer une image de ma ville » : par le partage de l'iPhone s'il accepte les fichiers, sinon par un téléchargement.
async function exportCityImage() {
  try {
    const out = await cityImageCanvas(), blob = await new Promise(resolve => out.toBlob(resolve, 'image/png'));
    if (!blob) throw new Error('toBlob');
    const filename = 'ma-ville-' + today() + '.png';
    if (isIOS() && typeof File === 'function') {
      const file = new File([blob], filename, { type: 'image/png' });
      if (navigator.canShare && navigator.canShare({ files: [file] })) { try { await navigator.share({ files: [file] }); return; } catch (e) { if (e && e.name === 'AbortError') return; } }
    }
    const url = URL.createObjectURL(blob), link = h('a', { href: url, download: filename, hidden: true });
    document.body.append(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 30000); toast(t('png.downloaded'));
  } catch (e) { toast(t('png.failed')); }
}


/* ---- 47-accessibility.js ---- */
/* Interactions clavier communes aux composants radio et aux fenêtres. */
function syncRadioGroups() {
  for (const group of $$('[role="radiogroup"]')) {
    const radios = $$('[role="radio"]', group).filter(r => !r.disabled);
    const selected = radios.find(r => r.getAttribute('aria-checked') === 'true') || radios[0];
    for (const radio of radios) radio.tabIndex = radio === selected ? 0 : -1;
  }
}
// Champ refusé à l'envoi d'un formulaire : un message traduit sous le champ, et le champ remis sous les yeux.
// Sur iPhone, la bulle du navigateur n'apparaît pas toujours (app installée, champ hors de l'écran) :
// « Enregistrer » semblait alors ne rien faire.
let fieldErrorSeq = 0;
function fieldErrorText(field) {
  const v = field.validity;
  if (v.valueMissing) return t('form.required');
  // Les bornes telles qu'on les tape, sans séparateur de milliers.
  if ((v.rangeUnderflow || v.rangeOverflow) && field.min && field.max) return t('form.range', { min: field.min, max: field.max });
  return t('form.check');
}
function showFieldError(field) {
  // Sous la rangée de deux champs s'il y en a une, pour que ses deux champs gardent la même hauteur.
  const place = field.closest('.row-2') || field.closest('.field') || field.closest('form');
  let note = place.querySelector('.field-error');
  if (!note) { note = h('p', { class: 'field-error', role: 'alert', id: 'field-error-' + ++fieldErrorSeq }); place.append(note); }
  note.textContent = frTypo(fieldErrorText(field));
  field.setAttribute('aria-invalid', 'true');
  field.setAttribute('aria-describedby', note.id);
  field.addEventListener('input', () => { note.remove(); field.removeAttribute('aria-invalid'); field.removeAttribute('aria-describedby'); }, { once: true });
}
// Un nom fait seulement d'espaces passe la validation du navigateur (le champ n'est pas vide), mais ce n'est pas un nom. Le formulaire vide alors
// le champ et rejoue la validation : « Ce champ est à remplir » s'affiche sous le champ, comme pour un champ laissé vide.
function rejectBlank(field) {
  field.value = '';
  field.form.reportValidity();
}
function setupAccessibility() {
  syncRadioGroups();
  let focusing = false;
  document.addEventListener('invalid', e => {
    const field = e.target;
    if (!field.closest || !field.closest('form')) return;
    e.preventDefault();
    showFieldError(field);
    if (focusing) return;
    // Le premier champ refusé seulement : les autres reçoivent leur message sans voler le focus.
    focusing = true;
    queueMicrotask(() => { focusing = false; });
    field.scrollIntoView({ block: 'center' });
    field.focus({ preventScroll: true });
  }, true);
  new MutationObserver(syncRadioGroups).observe(document.body, { childList: true, subtree: true, attributes: true, attributeFilter: ['aria-checked'] });
  document.addEventListener('keydown', e => {
    const radio = e.target.closest && e.target.closest('[role="radio"]');
    if (radio && ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(e.key)) {
      const group = radio.closest('[role="radiogroup"]');
      if (!group) return;
      const radios = $$('[role="radio"]', group).filter(r => !r.disabled);
      const index = radios.indexOf(radio), delta = ['ArrowLeft', 'ArrowUp'].includes(e.key) ? -1 : 1;
      const next = radios[e.key === 'Home' ? 0 : e.key === 'End' ? radios.length - 1 : (index + delta + radios.length) % radios.length];
      if (next) { e.preventDefault(); next.click(); next.focus(); syncRadioGroups(); }
      return;
    }
    if (e.key !== 'Tab') return;
    const scope = !$('#sheet').hidden ? $('#sheet') : !$('#session').hidden ? $('#session') : !$('#cityBig').hidden ? $('#cityBig') : null;
    if (!scope) return;
    const focusable = $$('button, input, select, textarea, a[href], [tabindex]', scope)
      .filter(el => !el.disabled && el.tabIndex >= 0 && !el.closest('[inert]') && el.getClientRects().length > 0);
    if (!focusable.length) return;
    const first = focusable[0], last = focusable[focusable.length - 1];
    if (e.shiftKey && (e.target === first || !focusable.includes(e.target))) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && (e.target === last || !scope.contains(e.target))) { e.preventDefault(); first.focus(); }
  });
}


